      "path": "src/DshDockLauncher.cs",
      "content": "// DshDockLauncher.cs — the single dsh-dock desktop launcher executable.\n//\n// One native exe replaces the old four-layer chain (.lnk -> wscript ->\n// launch-dsh.vbs -> dsh-card.exe/HTA). Everything lives in this one file:\n//\n//   quick path  : server alive -> read the freshest token line, verify it\n//                 really serves HTTP 200 (health gate with a cookie jar —\n//                 DSH answers the token URL with 303 + Set-Cookie), then\n//                 silently open the fullscreen Edge app window. No card UI.\n//   exit race   : a fresh .stopping marker means the server is mid-shutdown;\n//                 wait for the port to go down, then treat as cold start.\n//   cold start  : show the breathing whale card, settle-probe, take the\n//                 single-spawner lock, spawn start-server.cmd, poll, then\n//                 open the window the moment the token URL serves 200.\n//   stale server: port occupied by a non-responding / stale-token process\n//                 (card did not spawn it) -> explicit failure with guidance\n//                 instead of a 180 s silent wait.\n//\n// All paths (log, batch, profile, markers, whale png) come from\n// %USERPROFILE%\\.dsh\\launcher\\launcher.ini baked at install time, so the\n// binary itself is build-independent — no csc at install, no VBS/HTA fallback.\n//\n// Compile (scripts/build-launcher.ps1):\n//   csc /target:winexe /optimize+ /win32icon:assets/dsh-dock.ico\n//       /r:System.Windows.Forms.dll /r:System.Drawing.dll src/DshDockLauncher.cs\n//\n// Language level: C# 5 (the Windows-bundled .NET Framework 4 csc).\n\nusing System;\nusing System.Collections.Generic;\nusing System.Diagnostics;\nusing System.Drawing;\nusing System.IO;\nusing System.Net;\nusing System.Text.RegularExpressions;\nusing System.Threading;\nusing System.Windows.Forms;\nusing Microsoft.Win32;\n\n[assembly: System.Reflection.AssemblyTitle(\"dsh-dock-launcher\")]\n[assembly: System.Reflection.AssemblyProduct(\"dsh-dock\")]\n\nstatic class DshDockProgram\n{\n  public const int PortProbeMs = 700;    // TCP connect timeout for Probe()\n  public const int QuickRetries = 10;    // quick path re-scrape attempts\n  public const int QuickRetryMs = 500;\n  public const int RaceWaitMs = 15000;   // exit/start race absorption window\n  public const int MarkerFreshSec = 15;  // .stopping freshness (matches VBS)\n  public const int SpawnLockTakeoverSec = 60; // crashed-spawner lock takeover\n  public const int HttpTimeoutMs = 1500;\n  public const int GateThrottleMs = 600; // health-gate probe throttle\n  public const int GateFailLimit = 40;   // ~24s of non-200 -> explicit failure\n  public const int ProbeThrottleMs = 400; // card TCP probe throttle — a dead\n  // port blocks Probe() up to 700ms, so probing every 60ms tick would stall\n  // the message pump and freeze the breathing lamp for the whole cold boot.\n\n  /**\n   * Diagnostics: set DSH_DOCK_DIAG=1 to append decision/crash traces to\n   * %TEMP%\\dsh-dock-diag.log. Zero cost when unset — keep for field support.\n   */\n  static readonly bool DiagOn = Environment.GetEnvironmentVariable(\"DSH_DOCK_DIAG\") == \"1\";\n  internal static void Diag(string m)\n  {\n    if (!DiagOn) return;\n    try\n    {\n      File.AppendAllText(Path.Combine(Path.GetTempPath(), \"dsh-dock-diag.log\"),\n        DateTime.Now.ToString(\"HH:mm:ss.fff\") + \" \" + m + Environment.NewLine);\n    }\n    catch { }\n  }\n\n  /** JSON string literal via the serializer (escaping handled). */\n  internal static string JsonStr(string value)\n  {\n    try\n    {\n      return new System.Web.Script.Serialization.JavaScriptSerializer()\n        .Serialize(value ?? \"\");\n    }\n    catch { return \"\\\"\\\"\"; }\n  }\n\n  /** Tail of a log file (tokens redacted), for the early-exit failure card. */\n  internal static string ReadLogTail(string path, int maxChars)\n  {\n    try\n    {\n      if (string.IsNullOrEmpty(path) || !File.Exists(path)) return \"\";\n      using (var fs = new FileStream(path, FileMode.Open, FileAccess.Read,\n        FileShare.ReadWrite | FileShare.Delete))\n      {\n        long start = Math.Max(0, fs.Length - maxChars);\n        fs.Seek(start, SeekOrigin.Begin);\n        int want = (int)(fs.Length - start);\n        byte[] buf = new byte[want];\n        int n = fs.Read(buf, 0, want);\n        string s = System.Text.Encoding.UTF8.GetString(buf, 0, n);\n        s = RedactTokens(s);\n        if (s.Length > 260) s = s.Substring(s.Length - 260);\n        return s.Trim();\n      }\n    }\n    catch { return \"\"; }\n  }\n\n  /** Replace token values so crash dumps can never leak a session URL. */\n  internal static string RedactTokens(string s)\n  {\n    try { return Regex.Replace(s, \"token=[A-Za-z0-9_\\\\-]+\", \"token=…\"); }\n    catch { return s; }\n  }\n\n  [STAThread]\n  static void Main()\n  {\n    Application.EnableVisualStyles();\n    Application.SetCompatibleTextRenderingDefault(false);\n    Diag(\"main start\");\n    Application.ThreadException += (s, e) => Diag(\"ThreadException: \" + e.Exception);\n    AppDomain.CurrentDomain.UnhandledException += (s, e) =>\n      Diag(\"UnhandledException: \" + e.ExceptionObject);\n\n    LauncherConfig cfg;\n    try\n    {\n      Diag(\"config read in\");\n      cfg = LauncherConfig.Read();\n      Diag(\"config read ok url=\" + cfg.Url);\n    }\n    catch (Exception e)\n    {\n      Diag(\"config read FAIL: \" + e.Message);\n      MessageBox.Show(e.Message, \"DSH Harness\",\n        MessageBoxButtons.OK, MessageBoxIcon.Error);\n      return;\n    }\n\n    bool alive = ServerAlive(cfg.Url);\n    Diag(\"server alive: \" + alive + \" (url=\" + cfg.Url + \")\");\n\n    // --boot: HKCU Run autostart entry. Resident tray + silent server start,\n    // NO window (the preheated fast-open path). Never opens UI on its own.\n    bool boot = Array.IndexOf(Environment.GetCommandLineArgs(), \"--boot\") >= 0;\n    bool trayAlive = DshTray.IsRunning(cfg);\n    if (boot)\n    {\n      if (trayAlive) { Diag(\"boot: tray already running -> exit\"); return; }\n      Diag(\"boot mode -> tray\");\n      DshTray.Run(cfg, true);\n      return;\n    }\n\n    if (alive)\n    {\n      // Exit/start race: a double-click right after 完全退出 must not open\n      // the dying server. Wait the port down, then cold-start normally.\n      if (MarkerActive(cfg.Stopping) && WaitForPortDown(cfg, RaceWaitMs))\n      {\n        Diag(\"exit race: port down -> cold card\");\n        RunColdCard(cfg);\n        return;\n      }\n      // Quick path: open silently — no card UI — the moment the token URL\n      // really serves the page. If the log only holds a stale token (server\n      // still booting), retry a few times for a fresh line.\n      for (int i = 0; i < QuickRetries; i++)\n      {\n        string url = ReadTokenUrl(cfg.Log);\n        if (url != null && HttpReady(url))\n        {\n          Diag(\"quick open: \" + url);\n          LaunchEdge(url, cfg.Profile);\n          // v0.4.0: a non-boot launcher that just opened the window hands\n          // over to the resident tray (when enabled and none is running)\n          // instead of exiting — the whale stays as the status entry point.\n          MaybeEnterTray(cfg, trayAlive);\n          return;\n        }\n        Thread.Sleep(QuickRetryMs);\n      }\n      // Server answers but never serves a valid token URL: show the card in\n      // wait mode, which surfaces an explicit failure instead of waiting\n      // silently for 180 s.\n      Diag(\"quick path exhausted -> wait card\");\n      Application.Run(new DshCard(cfg, false, CandidateSet.Single(cfg), false));\n      return;\n    }\n\n    Diag(\"server dead -> cold card\");\n    RunColdCard(cfg);\n  }\n\n  /**\n   * Cold start entry: run the T2 refresh first so a dsh installed since the\n   * last server boot is already selectable, then let the card pick or start.\n   * When the card closes on a LIVE server (window opened / boot finished),\n   * the process may hand over to the resident tray instead of exiting.\n   */\n  static void RunColdCard(LauncherConfig cfg)\n  {\n    // Hygiene: the sidebar stop route's marker cleanup may be lost when the\n    // dying server's spawn chain collapses mid-script (observed in E2E). A\n    // stale marker is behaviorally inert (freshness gate) but untidy — clear\n    // it here, on a path that provably runs.\n    if (File.Exists(cfg.Stopping) && !MarkerActive(cfg.Stopping))\n    {\n      try { File.Delete(cfg.Stopping); } catch { }\n    }\n    bool refreshed = DshDockProgram.RunCandidateRefresh(cfg);\n    CandidateSet cands = CandidateSet.Load(cfg, refreshed);\n    bool stale = cands.HasRealList && !refreshed;\n    Application.Run(new DshCard(cfg, true, cands, stale));\n    if (ServerAlive(cfg.Url) && !MarkerActive(cfg.Stopping))\n    {\n      MaybeEnterTray(cfg, DshTray.IsRunning(cfg));\n    }\n  }\n\n  /** Enter tray residency when enabled and no tray is already running. */\n  static void MaybeEnterTray(LauncherConfig cfg, bool trayAlive)\n  {\n    if (trayAlive || !DshTray.ReadTrayStay(cfg)) return;\n    Diag(\"enter tray residency\");\n    DshTray.Run(cfg, false);\n  }\n\n  // ── quick-path helpers ───────────────────────────────────────────────────\n\n  /** Any HTTP answer (200, 401, ...) means the server process is alive. */\n  internal static bool ServerAlive(string url)\n  {\n    Diag(\"ServerAlive in: \" + url);\n    try\n    {\n      var req = (HttpWebRequest)WebRequest.Create(url);\n      req.Method = \"GET\";\n      req.Timeout = 1200;\n      req.ReadWriteTimeout = 1200;\n      req.Proxy = null;\n      req.AllowAutoRedirect = false;\n      using (var resp = (HttpWebResponse)req.GetResponse())\n      {\n        Diag(\"ServerAlive out: status=\" + (int)resp.StatusCode);\n        return true;\n      }\n    }\n    catch (WebException we)\n    {\n      Diag(\"ServerAlive out: WebException response=\" + (we.Response != null));\n      return we.Response != null;\n    }\n    catch (Exception e)\n    {\n      Diag(\"ServerAlive out: \" + e.GetType().Name + \" \" + e.Message);\n      return false;\n    }\n  }\n\n  /** True while the stop route is shutting the server down (marker fresh). */\n  internal static bool MarkerActive(string path)\n  {\n    try\n    {\n      long epochSec = long.Parse(File.ReadAllText(path).Trim());\n      long nowSec = (long)(DateTime.UtcNow - new DateTime(1970, 1, 1)).TotalSeconds;\n      return nowSec - epochSec < MarkerFreshSec;\n    }\n    catch { return false; }\n  }\n\n  /** Wait up to ms for the server port to actually go down. */\n  internal static bool WaitForPortDown(LauncherConfig cfg, int ms)\n  {\n    DateTime deadline = DateTime.UtcNow.AddMilliseconds(ms);\n    while (DateTime.UtcNow < deadline)\n    {\n      if (!ServerAlive(cfg.Url)) return true;\n      Thread.Sleep(250);\n    }\n    return !ServerAlive(cfg.Url);\n  }\n\n  /** Freshest `dsh web: http://…?token=…` line from the server log, or null. */\n  internal static string ReadTokenUrl(string logPath)\n  {\n    try\n    {\n      using (var fs = new FileStream(logPath, FileMode.Open, FileAccess.Read,\n        FileShare.ReadWrite | FileShare.Delete))\n      using (var rd = new StreamReader(fs))\n      {\n        MatchCollection ms = Regex.Matches(rd.ReadToEnd(),\n          \"dsh web: (http://[^ \\\\t\\\\r\\\\n]+)\");\n        if (ms.Count > 0) return ms[ms.Count - 1].Groups[1].Value;\n      }\n    }\n    catch { }\n    return null;\n  }\n\n  /**\n   * Health gate: only a token URL that really serves the page may open the\n   * window. DSH answers a VALID token URL with 303 + Set-Cookie -> \"/\"; the\n   * cookie jar lets the auto-redirect land on 200 exactly like a browser.\n   * A STALE token answers a plain 401 (no redirect) -> WebException -> false,\n   * so the launcher keeps waiting for a fresh line instead of opening a fake\n   * 401 window at a half-dead server.\n   */\n  internal static bool HttpReady(string url)\n  {\n    try\n    {\n      var req = (HttpWebRequest)WebRequest.Create(url);\n      req.Method = \"GET\";\n      req.Timeout = HttpTimeoutMs;\n      req.ReadWriteTimeout = HttpTimeoutMs;\n      req.Proxy = null;\n      req.CookieContainer = new CookieContainer();\n      using (var resp = (HttpWebResponse)req.GetResponse())\n      {\n        Diag(\"HttpReady \" + url + \" -> \" + (int)resp.StatusCode);\n        return resp.StatusCode == HttpStatusCode.OK;\n      }\n    }\n    catch (Exception e)\n    {\n      var we = e as WebException;\n      string detail = we != null && we.Response != null\n        ? \"status=\" + (int)((HttpWebResponse)we.Response).StatusCode\n        : e.GetType().Name + \": \" + e.Message;\n      Diag(\"HttpReady \" + url + \" -> FAIL (\" + detail + \")\");\n      return false;\n    }\n  }\n\n  /**\n   * Open the GUI as a fullscreen Edge app window (default browser fallback).\n   * Returns the spawned process (null via shell-open) so the tray can close\n   * the windows it opened on 完全退出.\n   */\n  internal static Process LaunchEdge(string url, string profile)\n  {\n    string edge = null;\n    string[] cands = {\n      Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),\n        \"Microsoft\\\\Edge\\\\Application\\\\msedge.exe\"),\n      Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),\n        \"Microsoft\\\\Edge\\\\Application\\\\msedge.exe\"),\n      Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),\n        \"Microsoft\\\\Edge\\\\Application\\\\msedge.exe\"),\n    };\n    foreach (string c in cands) if (File.Exists(c)) { edge = c; break; }\n    if (edge != null)\n    {\n      string args = \"--app=\\\"\" + url + \"\\\" --start-fullscreen --user-data-dir=\\\"\" + profile\n        + \"\\\" --no-first-run --no-default-browser-check\";\n      return Process.Start(edge, args);\n    }\n    Process.Start(url);\n    return null;\n  }\n\n  /**\n   * T2 candidate refresh: re-scan every installed dsh right before a cold\n   * start by running the deployed node script (it writes candidates.json and\n   * creates per-candidate batches — content-gated, never a rewrite of the\n   * selection itself). Returns false when refresh cannot run (old ini, node\n   * missing, timeout) so the caller can fall back to the stale list.\n   */\n  internal static bool RunCandidateRefresh(LauncherConfig cfg)\n  {\n    CandidateSet.EnsureDerivedPaths(cfg);\n    if (string.IsNullOrEmpty(cfg.Node) || string.IsNullOrEmpty(cfg.Refresh)\n      || !File.Exists(cfg.Node) || !File.Exists(cfg.Refresh))\n    {\n      Diag(\"refresh skipped: node/script missing\");\n      return false;\n    }\n    try\n    {\n      var psi = new ProcessStartInfo(cfg.Node, \"\\\"\" + cfg.Refresh + \"\\\"\")\n      {\n        UseShellExecute = false,\n        CreateNoWindow = true,\n      };\n      Diag(\"refresh start\");\n      Process p = Process.Start(psi);\n      if (p == null) return false;\n      if (!p.WaitForExit(8000))\n      {\n        try { p.Kill(); } catch { }\n        Diag(\"refresh timeout\");\n        return false;\n      }\n      Diag(\"refresh exit=\" + p.ExitCode);\n      return p.ExitCode == 0;\n    }\n    catch (Exception e)\n    {\n      Diag(\"refresh FAIL: \" + e.Message);\n      return false;\n    }\n  }\n}\n\n/** Bake-time configuration, read from %USERPROFILE%\\.dsh\\launcher\\launcher.ini. */\nsealed class LauncherConfig\n{\n  public string Url;\n  public string Log;\n  public string Batch;\n  public string Profile;\n  public string Stopping;\n  public string Lock;\n  public string Whale;\n  // v0.3.3 multi-DSH selection support.\n  public string Node;\n  public string Candidates;\n  public string State;\n  public string Refresh;\n  // v0.4.0 tray-resident support.\n  public string Settings;\n  public string Manifest;\n\n  public int Port\n  {\n    get\n    {\n      try { return new Uri(Url).Port; }\n      catch { return 3080; }\n    }\n  }\n\n  public static LauncherConfig Read()\n  {\n    string dir = Path.Combine(\n      Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),\n      \".dsh\", \"launcher\");\n    string ini = Path.Combine(dir, \"launcher.ini\");\n    if (!File.Exists(ini))\n    {\n      throw new InvalidOperationException(\n        \"缺少启动器配置 launcher.ini。请先安装 dsh-dock 插件并重启 dsh web。\");\n    }\n    var cfg = new LauncherConfig();\n    foreach (string raw in File.ReadAllLines(ini, System.Text.Encoding.UTF8))\n    {\n      // Defensive: strip a stray UTF-8 BOM before the first key.\n      string line = raw.Trim().TrimStart('\\uFEFF').Trim();\n      if (line.Length == 0 || line.StartsWith(\"#\")) continue;\n      int sep = line.IndexOf('=');\n      if (sep < 1) continue;\n      string key = line.Substring(0, sep).Trim();\n      string value = Decode(line.Substring(sep + 1).Trim(), key);\n      if (key == \"URL\") cfg.Url = value;\n      else if (key == \"LOG\") cfg.Log = value;\n      else if (key == \"BATCH\") cfg.Batch = value;\n      else if (key == \"PROFILE\") cfg.Profile = value;\n      else if (key == \"STOPPING\") cfg.Stopping = value;\n      else if (key == \"LOCK\") cfg.Lock = value;\n      else if (key == \"WHALE\") cfg.Whale = value;\n      else if (key == \"NODE\") cfg.Node = value;\n      else if (key == \"CANDIDATES\") cfg.Candidates = value;\n      else if (key == \"STATE\") cfg.State = value;\n      else if (key == \"REFRESH\") cfg.Refresh = value;\n      else if (key == \"SETTINGS\") cfg.Settings = value;\n      else if (key == \"MANIFEST\") cfg.Manifest = value;\n    }\n    if (string.IsNullOrEmpty(cfg.Url) || string.IsNullOrEmpty(cfg.Log)\n      || string.IsNullOrEmpty(cfg.Batch) || string.IsNullOrEmpty(cfg.Profile))\n    {\n      throw new InvalidOperationException(\"launcher.ini 缺少必要配置项 (URL/LOG/BATCH/PROFILE)。\");\n    }\n    return cfg;\n  }\n\n  static string Decode(string value, string key)\n  {\n    try\n    {\n      return System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(value));\n    }\n    catch\n    {\n      throw new InvalidOperationException(\"launcher.ini 的 \" + key + \" 值不是合法 Base64。\");\n    }\n  }\n}\n\n/** One selectable dsh installation (one baked batch file each). */\nsealed class CandidateRow\n{\n  public string Id;\n  public string Version;\n  public string Kind;\n  public string Path;\n  public string Label;\n  public string Batch;\n\n  public string BatchPath(LauncherConfig cfg)\n  {\n    // cfg.Batch points at the default start-server.cmd (row 0). Alternates\n    // live next to it under their own names.\n    string dir = System.IO.Path.GetDirectoryName(cfg.Batch);\n    if (string.IsNullOrEmpty(Batch)) return cfg.Batch;\n    // Defense in depth: only a bare filename may combine into the launcher\n    // dir. A tampered candidates.json could name an absolute path or a path\n    // with separators here (Path.Combine would run it verbatim); refuse and\n    // fall back to the canonical default batch instead.\n    if (System.IO.Path.IsPathRooted(Batch)\n      || Batch.IndexOfAny(new char[] { '\\\\', '/' }) >= 0)\n      return cfg.Batch;\n    if (dir == null) return Batch;\n    return System.IO.Path.Combine(dir, Batch);\n  }\n}\n\n/**\n * v0.3.3 candidate set — parsed from candidates.json (written by the host at\n * activation and refreshed by the T2 script before each cold start). Rows are\n * pre-sorted by the writer (version desc, then kind, then path). A missing or\n * unreadable file degrades to a single pseudo-candidate pointing at the baked\n * default batch, so pre-v0.3.3 suites behave exactly as before.\n */\nsealed class CandidateSet\n{\n  public List<CandidateRow> Rows = new List<CandidateRow>();\n  public bool NpxFallback = false;\n  /** True when rows came from a real candidates.json (not the pseudo default). */\n  public bool HasRealList = false;\n\n  /**\n   * An OLDER plugin release rewrites launcher.ini without the v0.3.3 keys\n   * (NODE/CANDIDATES/STATE/REFRESH) on every server boot, but it does not\n   * delete candidates.json or the deployed refresh script. Derive those\n   * paths from the default batch's directory so the picker still works\n   * under a stale ini instead of silently degrading to a single candidate.\n   */\n  internal static void EnsureDerivedPaths(LauncherConfig cfg)\n  {\n    string dir = string.IsNullOrEmpty(cfg.Batch) ? null : System.IO.Path.GetDirectoryName(cfg.Batch);\n    if (dir == null) return;\n    if (string.IsNullOrEmpty(cfg.Candidates)) cfg.Candidates = System.IO.Path.Combine(dir, \"candidates.json\");\n    if (string.IsNullOrEmpty(cfg.State)) cfg.State = System.IO.Path.Combine(dir, \"launcher-state.json\");\n    if (string.IsNullOrEmpty(cfg.Refresh)) cfg.Refresh = System.IO.Path.Combine(dir, \"dsh-dock-refresh.mjs\");\n  }\n\n  /** Degraded single-candidate set (old ini / missing list / wait-mode card). */\n  public static CandidateSet Single(LauncherConfig cfg)\n  {\n    var s = new CandidateSet();\n    s.Rows.Add(new CandidateRow { Id = \"default\", Version = \"\", Kind = \"default\",\n      Label = \"默认\", Batch = \"\" });\n    return s;\n  }\n\n  /** Load candidates.json. refreshOk = the T2 refresh just ran successfully. */\n  public static CandidateSet Load(LauncherConfig cfg, bool refreshOk)\n  {\n    var s = new CandidateSet();\n    EnsureDerivedPaths(cfg);\n    if (string.IsNullOrEmpty(cfg.Candidates) || !File.Exists(cfg.Candidates))\n      return Single(cfg);\n    try\n    {\n      string text = File.ReadAllText(cfg.Candidates, System.Text.Encoding.UTF8);\n      var ser = new System.Web.Script.Serialization.JavaScriptSerializer();\n      ser.MaxJsonLength = 1 << 20;\n      var root = ser.DeserializeObject(text) as System.Collections.Generic.Dictionary<string, object>;\n      if (root == null) return Single(cfg);\n      if (root.ContainsKey(\"candidates\"))\n      {\n        var list = root[\"candidates\"] as object[];\n        if (list != null)\n        {\n          foreach (object item in list)\n          {\n            var row = item as System.Collections.Generic.Dictionary<string, object>;\n            if (row == null) continue;\n            var r = new CandidateRow();\n            if (row.ContainsKey(\"id\")) r.Id = Convert.ToString(row[\"id\"]);\n            if (row.ContainsKey(\"version\")) r.Version = Convert.ToString(row[\"version\"]);\n            if (row.ContainsKey(\"kind\")) r.Kind = Convert.ToString(row[\"kind\"]);\n            if (row.ContainsKey(\"path\")) r.Path = Convert.ToString(row[\"path\"]);\n            if (row.ContainsKey(\"label\")) r.Label = Convert.ToString(row[\"label\"]);\n            if (row.ContainsKey(\"batch\")) r.Batch = Convert.ToString(row[\"batch\"]);\n            r.Label = string.IsNullOrEmpty(r.Label) ? \"默认\" : r.Label;\n            s.Rows.Add(r);\n          }\n        }\n      }\n      if (root.ContainsKey(\"npxFallback\"))\n      {\n        var fb = root[\"npxFallback\"];\n        if (fb != null) s.NpxFallback = true;\n      }\n      if (s.Rows.Count == 0 && !s.NpxFallback)\n      {\n        // candidates.json exists but lists nothing and there is no npx\n        // fallback — degrade to the baked default rather than a dead end.\n        return Single(cfg);\n      }\n      s.HasRealList = true;\n      return s;\n    }\n    catch (Exception e)\n    {\n      DshDockProgram.Diag(\"candidates parse FAIL: \" + e.Message);\n      return Single(cfg);\n    }\n  }\n\n  /** Version of the last successful run (state file), or null. */\n  public static string ReadLastVersion(LauncherConfig cfg)\n  {\n    EnsureDerivedPaths(cfg);\n    if (string.IsNullOrEmpty(cfg.State) || !File.Exists(cfg.State)) return null;\n    try\n    {\n      string text = File.ReadAllText(cfg.State, System.Text.Encoding.UTF8);\n      var ser = new System.Web.Script.Serialization.JavaScriptSerializer();\n      var root = ser.DeserializeObject(text) as System.Collections.Generic.Dictionary<string, object>;\n      if (root != null && root.ContainsKey(\"lastVersion\")) return Convert.ToString(root[\"lastVersion\"]);\n    }\n    catch { }\n    return null;\n  }\n\n  /** Persist the last successful (version, path) — called on a real open. */\n  public static void RecordRun(LauncherConfig cfg, CandidateRow row)\n  {\n    if (row == null) return;\n    EnsureDerivedPaths(cfg);\n    if (string.IsNullOrEmpty(cfg.State)) return;\n    try\n    {\n      string json = \"{\\\"lastVersion\\\":\" + DshDockProgram.JsonStr(row.Version)\n        + \",\\\"lastPath\\\":\" + DshDockProgram.JsonStr(row.Path)\n        + \",\\\"updatedAt\\\":\" + DateTime.UtcNow.Ticks + \"}\";\n      string dir = System.IO.Path.GetDirectoryName(cfg.State);\n      if (!string.IsNullOrEmpty(dir)) System.IO.Directory.CreateDirectory(dir);\n      System.IO.File.WriteAllText(cfg.State, json, new System.Text.UTF8Encoding(false));\n    }\n    catch { }\n  }\n}\n\n/** Breathing-whale cold-start card (also the wait/failure surface). */\nsealed class DshCard : Form\n{\n  readonly LauncherConfig cfg;\n  readonly bool coldStart;\n  readonly System.Windows.Forms.Timer anim = new System.Windows.Forms.Timer();\n  Thread poller = null;\n  volatile bool pollerStop = false;\n  readonly Label logline = new Label();\n  readonly Button closeBtn = new Button();\n  readonly Font uiFont = new Font(\"Segoe UI Light\", 11f);\n  readonly Font monoFont = new Font(\"Consolas\", 8.5f);\n  readonly Font titleFont = new Font(\"Segoe UI\", 12f, FontStyle.Bold);\n  readonly Font tagFont = new Font(\"Segoe UI\", 8.5f);\n  readonly Color bgTop = Color.FromArgb(28, 33, 42);\n  readonly Color bgBot = Color.FromArgb(20, 24, 31);\n  readonly Color ink = Color.FromArgb(200, 206, 216);\n  readonly Color dim = Color.FromArgb(128, 136, 148);\n  readonly Color danger = Color.FromArgb(240, 110, 100);\n  Bitmap whaleBmp = null;\n  System.Drawing.Imaging.ImageAttributes whaleAttrs = null;\n  System.Drawing.Imaging.ColorMatrix whaleMatrix = null;\n  Brush textInk = null;\n  Brush textDanger = null;\n  Pen borderPen = null;\n  string statusText = \"正在启动\";\n  float breatheT = 0f;\n  float fadeTarget = 0.90f;\n  int warmTicks = 0;\n  DateTime deadline;\n  DateTime lastHttpCheck = DateTime.MinValue;\n  DateTime lastProbe = DateTime.MinValue;\n  bool opened = false;\n  bool failing = false;\n  bool fadeOut = false;\n  bool spawned = false;\n  /** True while THIS process holds `.starting.lock` (only then may it clear it). */\n  bool holdsSpawnLock = false;\n  /** Height of the painted status box; the failure face grows it to fit (M3). */\n  int statusBoxH = 30;\n  int deadStreak = 0;\n  int gateFailStreak = 0;\n  Process spawnProc = null;\n  DateTime spawnAt = DateTime.MinValue;\n  const int W = 340;\n  const int HNormal = 184;\n  const int HFail = 284;\n  const int HZero = 204;\n  const int WhaleW = 84;\n  // v0.3.5 multi-DSH selection: a painted candidate list (no native ComboBox).\n  const int WMulti = 400;\n  const int HMulti = 288;\n  const int ListX = 24;\n  const int ListRowH = 46;\n  const int ListGap = 7;\n  const int ListTop = 88;\n  const int ListViewBottom = 244;   // bottom of the scrollable list viewport\n  readonly CandidateSet cands;\n  readonly bool stale;\n  readonly List<CandidateRow> rows = new List<CandidateRow>();\n  readonly Button npxBtn = new Button();\n  readonly Button cancelBtn = new Button();\n  int choiceMode = 0;        // 0 = none/single, 1 = picker, 2 = zero-candidate prompt\n  int chosenIndex = -1;\n  int keyIndex = 0;          // highlighted candidate; Enter/auto-start target\n  int hoverIndex = -1;\n  int scrollY = 0;           // scroll offset in px when the list overflows\n  string serverBatch = null;\n  bool chooseDone = false;\n  bool listVisible = false;\n  DateTime chooseDeadline = DateTime.MaxValue;\n  int lastHintSec = -1;\n  const int ChooseSeconds = 10;\n\n  public DshCard(LauncherConfig config, bool coldStart, CandidateSet cands, bool stale)\n  {\n    this.cfg = config;\n    this.coldStart = coldStart;\n    this.cands = cands ?? CandidateSet.Single(config);\n    this.stale = stale;\n    rows.AddRange(this.cands.Rows);\n    DshDockProgram.Diag(\"card ctor coldStart=\" + coldStart + \" port=\" + config.Port\n      + \" log=\" + config.Log + \" cands=\" + rows.Count + \" stale=\" + stale);\n\n    // Resolve the start target up front. The picker (mode 1) pauses spawn\n    // until the user picks or the countdown fires; the zero-prompt (mode 2)\n    // waits for an explicit npx/cancel click. Mode 0 (single candidate) is\n    // resolved in SetupChoiceControls.\n    if (coldStart)\n    {\n      if (rows.Count > 1) choiceMode = 1;\n      else if (rows.Count == 0) choiceMode = 2;\n    }\n\n    FormBorderStyle = FormBorderStyle.None;\n    StartPosition = FormStartPosition.CenterScreen;\n    ShowInTaskbar = false;\n    TopMost = true;\n    BackColor = bgBot;\n    DoubleBuffered = true;\n    SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint\n      | ControlStyles.UserPaint, true);\n    Size = new Size(W, HNormal);\n    Opacity = 0;\n\n    textInk = new SolidBrush(ink);\n    textDanger = new SolidBrush(danger);\n    borderPen = new Pen(Color.FromArgb(36, 255, 255, 255), 1f);\n\n    whaleMatrix = new System.Drawing.Imaging.ColorMatrix();\n    whaleAttrs = new System.Drawing.Imaging.ImageAttributes();\n    whaleAttrs.SetColorMatrix(whaleMatrix);\n    PreRenderWhale();\n\n    logline.Location = new Point(48, 148);\n    logline.Size = new Size(244, 40);\n    logline.Font = monoFont;\n    logline.ForeColor = dim;\n    logline.Visible = false;\n    Controls.Add(logline);\n\n    closeBtn.Location = new Point(120, 198);\n    closeBtn.Size = new Size(100, 28);\n    closeBtn.FlatStyle = FlatStyle.Flat;\n    closeBtn.FlatAppearance.BorderColor = Color.FromArgb(70, 76, 88);\n    closeBtn.FlatAppearance.MouseOverBackColor = Color.FromArgb(40, 46, 58);\n    closeBtn.BackColor = Color.FromArgb(32, 37, 48);\n    closeBtn.ForeColor = ink;\n    closeBtn.Font = new Font(\"Segoe UI\", 9f);\n    closeBtn.Text = \"关闭\";\n    closeBtn.Visible = false;\n    closeBtn.Click += delegate { fadeOut = true; fadeTarget = 0f; };\n    Controls.Add(closeBtn);\n\n    SetupChoiceControls();\n\n    anim.Interval = 16;\n    anim.Tick += delegate\n    {\n      if (warmTicks < 10) { warmTicks++; Invalidate(); return; }\n      breatheT += 0.011f;\n      if (breatheT > 1f) breatheT -= 1f;\n      float d = fadeTarget - (float)Opacity;\n      if (Math.Abs(d) > 0.003f) Opacity = Math.Max(0, Math.Min(1, Opacity + d * 0.10f));\n      else Opacity = fadeTarget;\n      if (fadeOut && Opacity <= 0.015) Close();\n      TickChoice();\n      Invalidate();\n    };\n    anim.Start();\n\n    Shown += delegate\n    {\n      Region = RoundedRegion(Width, Height, 20);\n      deadline = DateTime.UtcNow.AddSeconds(180);\n      // Provisional first status; the poller's first probe (within ~60ms)\n      // refines it — probing here would block this (UI) thread.\n      if (choiceMode == 1)\n      {\n        Size = new Size(WMulti, HMulti);\n        Region = RoundedRegion(WMulti, HMulti, 20);\n        SetStatus(\"正在选择要启动的 DSH\");\n        listVisible = true;\n        chooseDeadline = DateTime.UtcNow.AddSeconds(ChooseSeconds);\n        lastHintSec = -1;\n      }\n      else if (choiceMode == 2)\n      {\n        Size = new Size(W, HZero);\n        Region = RoundedRegion(W, HZero, 20);\n        SetStatus(\"未找到任何已安装的 DSH\");\n        npxBtn.Visible = true;\n        cancelBtn.Visible = true;\n        // Fetching via npx is a deliberate, networked action — no countdown.\n      }\n      else\n      {\n        SetStatus(coldStart ? \"正在启动\" : \"正在连接\");\n      }\n      poller = new Thread(PollerLoop);\n      poller.IsBackground = true;\n      poller.Name = \"dsh-dock-poller\";\n      poller.Start();\n    };\n  }\n\n  void PreRenderWhale()\n  {\n    try\n    {\n      string whalePath = cfg.Whale;\n      if (string.IsNullOrEmpty(whalePath) || !File.Exists(whalePath)) return;\n      Image src;\n      using (var fs = new FileStream(whalePath, FileMode.Open,\n        FileAccess.Read, FileShare.ReadWrite))\n      {\n        src = new Bitmap(fs);\n      }\n      int h = (int)(WhaleW * 17.04 / 23.16);\n      whaleBmp = new Bitmap(WhaleW, h);\n      using (var g = Graphics.FromImage(whaleBmp))\n      {\n        g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;\n        var attrs = new System.Drawing.Imaging.ImageAttributes();\n        var map = new System.Drawing.Imaging.ColorMap[1];\n        map[0] = new System.Drawing.Imaging.ColorMap();\n        map[0].OldColor = Color.Black;\n        map[0].NewColor = Color.FromArgb(225, 230, 240);\n        attrs.SetRemapTable(map);\n        g.DrawImage(src, new Rectangle(0, 0, WhaleW, h), 0, 0, src.Width, src.Height,\n          GraphicsUnit.Pixel, attrs);\n      }\n      src.Dispose();\n    }\n    catch { whaleBmp = null; }\n  }\n\n  /** Build the choice-phase controls: npx prompt (mode 2) and the painted\n   *  candidate-list geometry (mode 1); the list itself is drawn in OnPaint. */\n  void SetupChoiceControls()\n  {\n    keyIndex = 0;\n    scrollY = 0;\n    if (choiceMode == 1 && rows.Count > 0)\n    {\n      // Preselect the last successfully-run version when the list is real.\n      string lastV = cands.HasRealList ? CandidateSet.ReadLastVersion(cfg) : null;\n      if (lastV != null)\n      {\n        for (int i = 0; i < rows.Count; i++)\n        {\n          if (rows[i].Version == lastV) { keyIndex = i; break; }\n        }\n      }\n    }\n    else if (rows.Count > 0)\n    {\n      chosenIndex = 0;\n      serverBatch = rows[0].BatchPath(cfg);\n      chooseDone = true;\n    }\n\n    npxBtn.Location = new Point(26, 158);\n    npxBtn.Size = new Size(192, 30);\n    npxBtn.FlatStyle = FlatStyle.Flat;\n    npxBtn.FlatAppearance.BorderColor = Color.FromArgb(70, 76, 88);\n    npxBtn.FlatAppearance.MouseOverBackColor = Color.FromArgb(40, 46, 58);\n    npxBtn.BackColor = Color.FromArgb(32, 37, 48);\n    npxBtn.ForeColor = ink;\n    npxBtn.Font = new Font(\"Segoe UI\", 9f);\n    npxBtn.Text = \"用 npx 拉取并启动(需联网)\";\n    npxBtn.Visible = false;\n    npxBtn.Click += delegate\n    {\n      // cfg.Batch is the canonical npx-fallback batch when no candidate exists.\n      serverBatch = cfg.Batch;\n      chooseDone = true;\n      npxBtn.Visible = false;\n      cancelBtn.Visible = false;\n      SetStatus(\"正在通过 npx 获取最新版…\");\n    };\n    Controls.Add(npxBtn);\n\n    cancelBtn.Location = new Point(226, 158);\n    cancelBtn.Size = new Size(88, 30);\n    cancelBtn.FlatStyle = FlatStyle.Flat;\n    cancelBtn.FlatAppearance.BorderColor = Color.FromArgb(70, 76, 88);\n    cancelBtn.FlatAppearance.MouseOverBackColor = Color.FromArgb(40, 46, 58);\n    cancelBtn.BackColor = Color.FromArgb(32, 37, 48);\n    cancelBtn.ForeColor = ink;\n    cancelBtn.Font = new Font(\"Segoe UI\", 9f);\n    cancelBtn.Text = \"取消\";\n    cancelBtn.Visible = false;\n    cancelBtn.Click += delegate { fadeOut = true; fadeTarget = 0f; };\n    Controls.Add(cancelBtn);\n\n    KeyPreview = true;   // let the card see Up/Down/Enter before the buttons\n  }\n\n  /** 10s auto-start countdown for the picker (mode 1); no-op otherwise. */\n  void TickChoice()\n  {\n    if (choiceMode != 1 || chooseDone) return;\n    double left = (chooseDeadline - DateTime.UtcNow).TotalSeconds;\n    if (left <= 0)\n    {\n      DoChoose(keyIndex >= 0 && keyIndex < rows.Count ? keyIndex : 0);\n      return;\n    }\n    int secs = (int)Math.Ceiling(left);\n    if (secs != lastHintSec)\n    {\n      lastHintSec = secs;\n      Invalidate();   // the countdown is painted in OnPaint\n    }\n  }\n\n  /** Lock in the picker selection and allow the spawn path to proceed. */\n  void DoChoose(int index)\n  {\n    if (chooseDone || choiceMode != 1) return;\n    if (index < 0 || index >= rows.Count) index = 0;\n    chosenIndex = index;\n    serverBatch = rows[index].BatchPath(cfg);\n    chooseDone = true;\n    listVisible = false;\n    hoverIndex = -1;\n    DshDockProgram.Diag(\"chosen: \" + rows[index].Label + \" batch=\" + serverBatch);\n    SetStatus(\"正在启动 \" + rows[index].Label);\n    // Settle the card back to the single-candidate startup size.\n    Size = new Size(W, HNormal);\n    Region = RoundedRegion(W, HNormal, 20);\n    Invalidate();\n  }\n\n  /** Marshal a UI update onto the message loop (safe once the form is shown). */\n  void Ui(MethodInvoker a)\n  {\n    try { if (!IsDisposed) BeginInvoke(a); }\n    catch (ObjectDisposedException) { }\n    catch (InvalidOperationException) { }\n  }\n\n  void SetStatus(string t)\n  {\n    Ui(delegate { statusText = t; failing = false; Invalidate(); });\n  }\n\n  /** Re-read the log, health-gate the token URL, and open on success. */\n  bool TryOpenFromLog()\n  {\n    string url = DshDockProgram.ReadTokenUrl(cfg.Log);\n    if (url == null) return false;\n    if (!DshDockProgram.HttpReady(url)) return false;\n    Open(url);\n    return true;\n  }\n\n  void Open(string url)\n  {\n    DshDockProgram.Diag(\"card open: \" + url);\n    opened = true;\n    pollerStop = true;\n    // Remember the version that really served the page — the next cold start\n    // preselects it. Only recorded on success, never on a failed pick.\n    if (cands.HasRealList && chosenIndex >= 0 && chosenIndex < rows.Count)\n    {\n      CandidateSet.RecordRun(cfg, rows[chosenIndex]);\n    }\n    TryClearSpawnLock();\n    holdsSpawnLock = false;\n    DshDockProgram.LaunchEdge(url, cfg.Profile);\n    Ui(delegate\n    {\n      statusText = \"已就绪\";\n      fadeOut = true;\n      fadeTarget = 0f;\n      Invalidate();\n    });\n  }\n\n  /**\n   * All blocking I/O — the TCP probe (a dead port blocks up to 700ms), the\n   * log scrape, and the health-gate HTTP call (up to 1.5s) — runs on this\n   * background thread; the UI thread only paints. These used to run inside\n   * a WinForms timer tick, freezing the message pump and stuttering the\n   * breathing lamp on every poll — machine-independent, because a kernel\n   * connect timeout is not CPU work.\n   */\n  void PollerLoop()\n  {\n    while (!pollerStop)\n    {\n      try { PollOnce(); }\n      catch (Exception ex) { DshDockProgram.Diag(\"poller tick FAIL: \" + ex.Message); }\n      if (pollerStop) break;\n      Thread.Sleep(60);\n    }\n    DshDockProgram.Diag(\"poller exit\");\n  }\n\n  void PollOnce()\n  {\n    if (failing || opened) { pollerStop = true; return; }\n    if (coldStart)\n    {\n      // Probe at most every ProbeThrottleMs: a dead port blocks the TCP\n      // connect up to 700ms, and doing that on every 60ms tick would freeze\n      // the breathing animation for the whole server boot.\n      bool probed = (DateTime.UtcNow - lastProbe).TotalMilliseconds\n        >= DshDockProgram.ProbeThrottleMs;\n      bool up = false;\n      if (probed)\n      {\n        lastProbe = DateTime.UtcNow;\n        up = Probe();\n      }\n      if (up)\n      {\n        deadStreak = 0;\n        if ((DateTime.UtcNow - lastHttpCheck).TotalMilliseconds\n          >= DshDockProgram.GateThrottleMs)\n        {\n          lastHttpCheck = DateTime.UtcNow;\n          if (TryOpenFromLog()) return;\n          statusText = \"正在连接\";\n        }\n        return;\n      }\n      // Multi-DSH / zero-prompt: the user picks (or the countdown fires)\n      // before we may spawn — probes above still detect an external start.\n      if (!chooseDone) return;\n      if (probed && !spawned)\n      {\n        // Settle guard (port must stay down) PLUS a single-spawner lock: the\n        // cold boot keeps the port dead ~10s+, so settle checks alone cannot\n        // stop a second double-click from spawning a duplicate server.\n        deadStreak++;\n        // Only a lock we actually TOOK may latch `spawned`. Latching a failed\n        // attempt killed every later retry in this process (the guard above is\n        // dead once spawned is true), so the natural retry after a fast failure\n        // waited out the full 180s against a still-fresh lock file.\n        if (deadStreak >= 3 && TryTakeSpawnLock())\n        {\n          holdsSpawnLock = true;\n          spawned = true;\n          statusText = \"首次启动可能稍久\";\n          try { StartServer(); } catch (Exception ex) { Fail(ex.Message); }\n        }\n        return;\n      }\n      // Early-exit detection: the chosen batch died without ever listening —\n      // fail with the log tail instead of making the user wait out 180 s.\n      if (spawned && !opened && spawnProc != null && spawnAt != DateTime.MinValue\n        && (DateTime.UtcNow - spawnAt).TotalSeconds > 4)\n      {\n        try\n        {\n          if (spawnProc.HasExited && !Probe())\n          {\n            string tail = DshDockProgram.ReadLogTail(cfg.Log + \".err\", 300);\n            DshDockProgram.Diag(\"spawn exited early; err tail len=\" + tail.Length);\n            Fail(\"所选 DSH 启动后立即退出,未能监听端口 \" + cfg.Port\n              + \"(依赖缺失或需其它启动方式)。\",\n              \"日志尾部:\" + (tail.Length == 0 ? \"无\" : tail) + \"\\n日志:\" + cfg.Log);\n            return;\n          }\n        }\n        catch { }\n      }\n      if (DateTime.UtcNow > deadline)\n      {\n        Fail(\"服务器在 180 秒内未就绪(端口 \" + cfg.Port\n          + \")。若服务器由手动命令启动,请直接用浏览器打开 \" + cfg.Url\n          + \"。日志:\" + cfg.Log);\n      }\n    }\n    else\n    {\n      // Wait mode: the server answers HTTP but never serves a valid token\n      // URL. Keep polling with the health gate, but surface an explicit\n      // failure (~24 s) instead of a silent 180 s wait — and tailor the\n      // guidance to the port's actual state (occupied vs. already gone).\n      if (!opened && (DateTime.UtcNow - lastHttpCheck).TotalMilliseconds\n        >= DshDockProgram.GateThrottleMs)\n      {\n        lastHttpCheck = DateTime.UtcNow;\n        if (TryOpenFromLog()) return;\n        gateFailStreak++;\n        if (gateFailStreak >= DshDockProgram.GateFailLimit)\n        {\n          if (Probe())\n          {\n            Fail(\"端口 \" + cfg.Port + \" 已被占用,但 DSH 页面未就绪(上一次会话可能未完全退出,\"\n              + \"或服务器由手动命令启动)。请结束占用 \" + cfg.Port + \" 端口的进程,\"\n              + \"或直接用浏览器打开 \" + cfg.Url + \"。日志:\" + cfg.Log);\n          }\n          else\n          {\n            Fail(\"服务器已停止响应。请再次双击以重新启动。日志:\" + cfg.Log);\n          }\n        }\n      }\n    }\n  }\n\n  void Fail(string msg)\n  {\n    Fail(msg, null);\n  }\n\n  /**\n   * Failure face. `detail` (the .err tail + the log path) is assigned INSIDE the\n   * queued delegate: setting it from the poller thread raced with this delegate\n   * and always lost, so the richest diagnostic never reached the user.\n   */\n  void Fail(string msg, string detail)\n  {\n    failing = true;\n    pollerStop = true;\n    ReleaseSpawnLockIfHeld();\n    Ui(delegate\n    {\n      statusText = \"启动失败:\" + msg;\n      LayoutFailureFace(statusText);\n      logline.Text = string.IsNullOrEmpty(detail) ? (\"日志:\" + cfg.Log) : detail;\n      logline.Visible = true;\n      closeBtn.Visible = true;\n      Invalidate();\n    });\n  }\n\n  /** Give the failure face the height its remedy text needs (see M3). */\n  void LayoutFailureFace(string text)\n  {\n    Size measured = TextRenderer.MeasureText(text, uiFont, new Size(W - 44, int.MaxValue),\n      TextFormatFlags.WordBreak);\n    statusBoxH = Math.Max(30, measured.Height + 8);\n    int extra = statusBoxH - 30;\n    int height = HFail + extra;\n    Size = new Size(W, height);\n    Region = RoundedRegion(W, height, 20);\n    logline.Location = new Point(48, 148 + extra);\n    closeBtn.Location = new Point(120, 198 + extra);\n  }\n\n  /**\n   * Drop the spawn lock only when THIS process took it. Deleting another\n   * launcher's fresh lock would let a third double-click spawn a duplicate\n   * server while the peer is still booting.\n   */\n  void ReleaseSpawnLockIfHeld()\n  {\n    if (!holdsSpawnLock) return;\n    holdsSpawnLock = false;\n    TryClearSpawnLock();\n  }\n\n  protected override void OnFormClosed(FormClosedEventArgs e)\n  {\n    pollerStop = true;\n    // A card closed (or crashed) mid-spawn must not leave a fresh lock behind:\n    // the user's next double-click would fail to take it and, before the fix\n    // above, never retried.\n    ReleaseSpawnLockIfHeld();\n    base.OnFormClosed(e);\n  }\n\n  /** Release the GDI+ resources this card owns. */\n  protected override void Dispose(bool disposing)\n  {\n    if (disposing)\n    {\n      if (whaleBmp != null) whaleBmp.Dispose();\n      if (textInk != null) textInk.Dispose();\n      if (textDanger != null) textDanger.Dispose();\n      if (borderPen != null) borderPen.Dispose();\n      if (whaleAttrs != null) whaleAttrs.Dispose();\n      if (uiFont != null) uiFont.Dispose();\n      if (monoFont != null) monoFont.Dispose();\n      if (titleFont != null) titleFont.Dispose();\n      if (tagFont != null) tagFont.Dispose();\n      anim.Stop();\n      anim.Dispose();\n    }\n    base.Dispose(disposing);\n  }\n\n  protected override void OnPaint(PaintEventArgs e)\n  {\n    var g = e.Graphics;\n    g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;\n    g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;\n\n    using (var bgGrad = new System.Drawing.Drawing2D.LinearGradientBrush(\n      new Rectangle(0, 0, Width, Height), bgTop, bgBot, 90f))\n    {\n      var oldClip = g.Clip;\n      g.SetClip(RoundedPath(0, 0, Width, Height, 20));\n      g.FillRectangle(bgGrad, 0, 0, Width, Height);\n      g.Clip = oldClip;\n    }\n\n    g.DrawPath(borderPen, RoundedPath(0.5f, 0.5f, Width - 1f, Height - 1f, 19f));\n\n    if (choiceMode == 1 && listVisible && !chooseDone) PaintCandidateList(g);\n    else PaintWhaleAndStatus(g);\n  }\n\n  /** The single-candidate / zero / fail / post-choice face. */\n  void PaintWhaleAndStatus(Graphics g)\n  {\n    if (whaleBmp != null)\n    {\n      int whaleH = whaleBmp.Height;\n      int wx = (Width - WhaleW) / 2;\n      int wy = 32;\n      if (failing) g.DrawImage(whaleBmp, wx, wy);\n      else\n      {\n        float lamp = (float)(0.35 + 0.65 * (0.5 - 0.5 * Math.Cos(breatheT * 2 * Math.PI)));\n        whaleMatrix.Matrix33 = lamp;\n        whaleAttrs.SetColorMatrix(whaleMatrix);\n        g.DrawImage(whaleBmp, new Rectangle(wx, wy, WhaleW, whaleH),\n          0, 0, WhaleW, whaleH, GraphicsUnit.Pixel, whaleAttrs);\n      }\n    }\n    var sf = new StringFormat();\n    sf.Alignment = StringAlignment.Center;\n    sf.LineAlignment = StringAlignment.Center;\n    int statusY = (choiceMode == 2) ? 112 : 138;\n    using (var brush = new SolidBrush(failing ? danger : dim))\n    {\n      g.DrawString(statusText, uiFont, brush,\n        new RectangleF(0, statusY, Width, failing ? statusBoxH : 30), sf);\n    }\n  }\n\n  /** Multi-DSH face: a painted, scrollable candidate list matching the chrome. */\n  void PaintCandidateList(Graphics g)\n  {\n    // Brand whale, centered at the top (a bit bigger than a thumbnail).\n    if (whaleBmp != null)\n    {\n      int smallW = 64, smallH = (int)(smallW * (float)whaleBmp.Height / whaleBmp.Width);\n      int wx = (Width - smallW) / 2, wy = 12;\n      float lamp = (float)(0.35 + 0.65 * (0.5 - 0.5 * Math.Cos(breatheT * 2 * Math.PI)));\n      whaleMatrix.Matrix33 = lamp;\n      whaleAttrs.SetColorMatrix(whaleMatrix);\n      g.DrawImage(whaleBmp, new Rectangle(wx, wy, smallW, smallH),\n        0, 0, whaleBmp.Width, whaleBmp.Height, GraphicsUnit.Pixel, whaleAttrs);\n    }\n\n    using (var titleBrush = new SolidBrush(Color.FromArgb(220, 226, 234)))\n    {\n      var sf = new StringFormat();\n      sf.Alignment = StringAlignment.Center;\n      g.DrawString(\"选择要启动的 DSH\", titleFont, titleBrush, new RectangleF(0, 60, Width, 24), sf);\n    }\n\n    int viewH = ListViewBottom - ListTop;\n    int maxScroll = ComputeMaxScroll();\n    int rowW = WMulti - 2 * ListX;\n    using (var rowFill = new SolidBrush(Color.FromArgb(30, 36, 46)))\n    using (var hoverFill = new SolidBrush(Color.FromArgb(44, 52, 66)))\n    using (var selBorder = new Pen(Color.FromArgb(160, 195, 235), 1.6f))\n    using (var mainBrush = new SolidBrush(ink))\n    using (var dimBrush = new SolidBrush(dim))\n    using (var checkPen = new Pen(Color.FromArgb(130, 210, 160), 2f))\n    {\n      for (int i = 0; i < rows.Count; i++)\n      {\n        int y = ListTop + i * (ListRowH + ListGap) - scrollY;\n        if (y + ListRowH < ListTop || y > ListTop + viewH) continue;  // off-viewport\n        var r = new Rectangle(ListX, y, rowW, ListRowH);\n        bool sel = i == keyIndex;\n        bool hov = i == hoverIndex;\n        using (var path = RoundedPath(r.X, r.Y, r.Width, r.Height, 9))\n        {\n          g.FillPath(hov ? hoverFill : rowFill, path);\n          if (sel) g.DrawPath(selBorder, path);\n        }\n        var mr = new Rectangle(r.X + 14, r.Y + 8, r.Width - 14 - 32, 20);\n        DrawEllipsis(g, rows[i].Label, uiFont, mainBrush, mr);\n        var pr = new Rectangle(r.X + 14, r.Y + 26, r.Width - 14 - 32, 16);\n        DrawEllipsis(g, PathTail(rows[i].Path), monoFont, dimBrush, pr);\n        if (sel)\n        {\n          float cx = r.Right - 20, cy = r.Top + r.Height / 2f;\n          g.DrawLines(checkPen, new PointF[] {\n            new PointF(cx - 5, cy), new PointF(cx - 1, cy + 4), new PointF(cx + 6, cy - 4) });\n        }\n      }\n      // thin scrollbar thumb when the list overflows\n      if (maxScroll > 0)\n      {\n        int trackW = 4, tx = WMulti - 14;\n        float thumbH = Math.Max(24f, viewH * (float)viewH / (viewH + maxScroll));\n        float ty = ListTop + (float)scrollY / maxScroll * Math.Max(0, viewH - thumbH);\n        using (var thumb = new SolidBrush(Color.FromArgb(110, 120, 134)))\n        using (var tp = RoundedPath(tx, (int)ty, trackW, (int)thumbH, 2))\n          g.FillPath(thumb, tp);\n      }\n    }\n\n    // footer: countdown (right) + overflow/stale note (center)\n    var sfC = new StringFormat();\n    sfC.Alignment = StringAlignment.Far;\n    if (!chooseDone)\n    {\n      double left = Math.Max(0, (chooseDeadline - DateTime.UtcNow).TotalSeconds);\n      int secs = (int)Math.Ceiling(left);\n      using (var hint = new SolidBrush(dim))\n        g.DrawString(secs + \" 秒后自动启动\", monoFont, hint,\n          new RectangleF(12, HMulti - 34, Width - 24, 18), sfC);\n    }\n    string note = null;\n    if (maxScroll > 0) note = \"共 \" + rows.Count + \" 个候选 · 滚轮 / ↑↓ 选择\";\n    else if (stale && cands.HasRealList) note = \"候选列表可能已过期\";\n    if (note != null)\n    {\n      using (var nb = new SolidBrush(Color.FromArgb(150, 158, 170)))\n      {\n        var sn = new StringFormat();\n        sn.Alignment = StringAlignment.Center;\n        g.DrawString(note, tagFont, nb, new RectangleF(0, HMulti - 20, Width, 16), sn);\n      }\n    }\n  }\n\n  /** Right-anchored path tail so the install dir is recognizable in a row. */\n  string PathTail(string p)\n  {\n    if (string.IsNullOrEmpty(p)) return p;\n    var segs = p.Split(new[] { '\\\\', '/' }, StringSplitOptions.RemoveEmptyEntries);\n    if (segs.Length <= 3) return p;\n    return \"…\\\\\" + segs[segs.Length - 2] + \"\\\\\" + segs[segs.Length - 1];\n  }\n\n  /** How far the list can scroll (0 = fits). */\n  int ComputeMaxScroll()\n  {\n    int viewH = ListViewBottom - ListTop;\n    int contentH = rows.Count * ListRowH + (rows.Count > 0 ? (rows.Count - 1) * ListGap : 0);\n    return Math.Max(0, contentH - viewH);\n  }\n\n  int RowRectAt(Point p)\n  {\n    int rowW = WMulti - 2 * ListX;\n    for (int i = 0; i < rows.Count; i++)\n    {\n      int y = ListTop + i * (ListRowH + ListGap) - scrollY;\n      if (p.X >= ListX && p.X <= ListX + rowW && p.Y >= y && p.Y < y + ListRowH) return i;\n    }\n    return -1;\n  }\n\n  /** Keep the highlighted row inside the scroll viewport. */\n  void EnsureKeyVisible()\n  {\n    int max = ComputeMaxScroll();\n    if (max <= 0) { scrollY = 0; return; }\n    int top = ListTop + keyIndex * (ListRowH + ListGap) - scrollY;\n    int bot = top + ListRowH;\n    int viewH = ListViewBottom - ListTop;\n    if (top < ListTop) scrollY -= (ListTop - top);\n    else if (bot > ListTop + viewH) scrollY += (bot - (ListTop + viewH));\n    if (scrollY < 0) scrollY = 0;\n    if (scrollY > max) scrollY = max;\n  }\n\n  protected override void OnMouseWheel(MouseEventArgs e)\n  {\n    base.OnMouseWheel(e);\n    if (choiceMode != 1 || !listVisible || chooseDone) return;\n    int max = ComputeMaxScroll();\n    if (max <= 0) return;\n    scrollY -= (e.Delta > 0 ? 40 : -40);\n    if (scrollY < 0) scrollY = 0;\n    if (scrollY > max) scrollY = max;\n    var handled = e as HandledMouseEventArgs;\n    if (handled != null) handled.Handled = true;\n    Invalidate();\n  }\n\n  void DrawEllipsis(Graphics g, string text, Font font, Brush brush, Rectangle rect)\n  {\n    if (string.IsNullOrEmpty(text)) return;\n    TextRenderer.DrawText(g, text, font, rect, ((SolidBrush)brush).Color,\n      TextFormatFlags.SingleLine | TextFormatFlags.Left\n      | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis\n      | TextFormatFlags.NoPrefix);\n  }\n\n  protected override void OnMouseMove(MouseEventArgs e)\n  {\n    base.OnMouseMove(e);\n    if (choiceMode != 1 || !listVisible || chooseDone) return;\n    int h = RowRectAt(e.Location);\n    if (h != hoverIndex)\n    {\n      hoverIndex = h;\n      Cursor = h >= 0 ? Cursors.Hand : Cursors.Default;\n      Invalidate();\n    }\n  }\n\n  protected override void OnMouseLeave(EventArgs e)\n  {\n    base.OnMouseLeave(e);\n    if (hoverIndex != -1) { hoverIndex = -1; Cursor = Cursors.Default; Invalidate(); }\n  }\n\n  protected override void OnMouseClick(MouseEventArgs e)\n  {\n    base.OnMouseClick(e);\n    if (choiceMode != 1 || !listVisible || chooseDone) return;\n    if (e.Button != MouseButtons.Left) return;\n    int i = RowRectAt(e.Location);\n    if (i >= 0) DoChoose(i);\n  }\n\n  protected override void OnKeyDown(KeyEventArgs e)\n  {\n    base.OnKeyDown(e);\n    if (choiceMode != 1 || !listVisible || chooseDone) return;\n    if (e.KeyCode == Keys.Up) { keyIndex = Math.Max(0, keyIndex - 1); EnsureKeyVisible(); Invalidate(); e.Handled = true; }\n    else if (e.KeyCode == Keys.Down) { keyIndex = Math.Min(rows.Count - 1, keyIndex + 1); EnsureKeyVisible(); Invalidate(); e.Handled = true; }\n    else if (e.KeyCode == Keys.Enter || e.KeyCode == Keys.Space) { DoChoose(keyIndex); e.Handled = true; }\n    else if (e.KeyCode == Keys.Escape) { fadeOut = true; fadeTarget = 0f; e.Handled = true; }\n  }\n\n  static System.Drawing.Drawing2D.GraphicsPath RoundedPath(float x, float y, float w, float h, float r)\n  {\n    var p = new System.Drawing.Drawing2D.GraphicsPath();\n    p.AddArc(x, y, r, r, 180, 90);\n    p.AddArc(x + w - r, y, r, r, 270, 90);\n    p.AddArc(x + w - r, y + h - r, r, r, 0, 90);\n    p.AddArc(x, y + h - r, r, r, 90, 90);\n    p.CloseFigure();\n    return p;\n  }\n\n  bool Probe()\n  {\n    string host = \"127.0.0.1\";\n    try { host = new Uri(cfg.Url).Host; } catch { }\n    try\n    {\n      using (var c = new System.Net.Sockets.TcpClient())\n      {\n        var ok = c.BeginConnect(host, cfg.Port, null, null);\n        bool done = ok.AsyncWaitHandle.WaitOne(DshDockProgram.PortProbeMs);\n        if (done && c.Connected) { c.Close(); return true; }\n      }\n    }\n    catch { }\n    return false;\n  }\n\n  void StartServer()\n  {\n    string target = serverBatch ?? cfg.Batch;\n    DshDockProgram.Diag(\"spawn batch: \" + target);\n    var pi = new ProcessStartInfo(\"cmd.exe\", \"/c \\\"\" + target + \"\\\"\")\n    {\n      UseShellExecute = false,\n      CreateNoWindow = true,\n    };\n    try\n    {\n      spawnProc = Process.Start(pi);\n      spawnAt = DateTime.UtcNow;\n    }\n    catch (Exception ex)\n    {\n      spawnProc = null;\n      throw ex;\n    }\n  }\n\n  /** Single-spawner lock: of N racing launchers exactly one starts the server;\n   *  a crashed spawner's lock is taken over after 60 s. */\n  bool TryTakeSpawnLock()\n  {\n    string lp = cfg.Lock;\n    try\n    {\n      using (var fs = new FileStream(lp, FileMode.CreateNew, FileAccess.Write))\n      {\n        byte[] b = System.Text.Encoding.UTF8.GetBytes(DateTime.UtcNow.Ticks.ToString());\n        fs.Write(b, 0, b.Length);\n      }\n      return true;\n    }\n    catch { }\n    try\n    {\n      var fi = new FileInfo(lp);\n      if (fi.Exists && DateTime.UtcNow - fi.LastWriteTimeUtc\n        > TimeSpan.FromSeconds(DshDockProgram.SpawnLockTakeoverSec))\n      {\n        try { File.Delete(lp); } catch { }\n        try\n        {\n          using (var fs = new FileStream(lp, FileMode.CreateNew, FileAccess.Write))\n          {\n            byte[] b = System.Text.Encoding.UTF8.GetBytes(DateTime.UtcNow.Ticks.ToString());\n            fs.Write(b, 0, b.Length);\n          }\n          return true;\n        }\n        catch { }\n      }\n    }\n    catch { }\n    return false;\n  }\n\n  void TryClearSpawnLock()\n  {\n    try { if (File.Exists(cfg.Lock)) File.Delete(cfg.Lock); } catch { }\n  }\n\n  static Region RoundedRegion(int w, int h, int r)\n  {\n    var path = new System.Drawing.Drawing2D.GraphicsPath();\n    path.AddArc(0, 0, r, r, 180, 90);\n    path.AddArc(w - r, 0, r, r, 270, 90);\n    path.AddArc(w - r, h - r, r, r, 0, 90);\n    path.AddArc(0, h - r, r, r, 90, 90);\n    path.CloseFigure();\n    return new Region(path);\n  }\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// v0.4.0 tray residency: the whale lives in the notification area as the\n// permanent status entry point. Tooltip reflects server state (probe on a\n// background thread — a dead port blocks up to 700ms); the menu offers\n// 打开 DSH / 重启服务器 / ☑开机自启 / ⏻完全退出 (single click, per user\n// preference). The tray stamps its PID into launcher.json so the host stop\n// route can clean it up, and its 完全退出 mirrors the host sequence:\n// marker -> kill listener -> close every dock Edge window (by profile\n// identity, not spawn bookkeeping) -> clear marker -> vanish.\n//\n// v0.8 adaptive pacing: the poll loop keeps its fast 1.5s cadence only while a\n// human is waiting on a transition (boot/restart/open-when-ready); a steady\n// running server relaxes to 15s, and the sidebar restart request is delivered\n// by a file watcher instead of being noticed on the next tick.\n// ─────────────────────────────────────────────────────────────────────────────\n\nsealed class DshTray\n{\n  const string RunKeySub = \"Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Run\";\n  const string RunValueName = \"dsh-dock\";\n  // Adaptive poll cadence (v0.8). The tray is a separate process with no IPC,\n  // so it discovers the world by polling — but only the TRANSITIONS need a fast\n  // cadence. A steady running server needs none of it: the sidebar restart\n  // request now arrives through a file watcher (instant), so the probe relaxes\n  // to 15s. Before this, every resident tray sent ~57,600 HTTP requests a day\n  // for a state that changes a few times a day.\n  const int PollActiveMs = 1500;  // starting / restarting / waiting to open\n  const int PollIdleMs = 5000;    // dead or failed: the server may come up from anywhere\n  const int PollSteadyMs = 15000; // running, nothing pending\n\n  readonly LauncherConfig cfg;\n  readonly bool boot;\n  readonly NotifyIcon icon = new NotifyIcon();\n  readonly List<Process> edgeWindows = new List<Process>();\n  Mutex gate = null; // single-instance mutex held for the tray's lifetime\n  Thread poller = null;\n  /** Wakes the poll loop out of its adaptive wait the moment the sidebar writes\n   *  .restart.request, so a long steady-state interval costs no restart latency. */\n  readonly ManualResetEventSlim wake = new ManualResetEventSlim(false);\n  FileSystemWatcher restartWatch = null;\n  volatile bool watchOk = false;       // false => stay on the fast cadence\n  volatile bool stopping = false;\n  volatile bool pendingOpen = false;   // open the window the moment ready\n  volatile bool spawnWanted = false;   // spawn the batch when port is dead\n  bool spawned = false;\n  Process spawnProc = null;\n  DateTime spawnAt = DateTime.MinValue;\n  string state = \"starting\";           // starting | running | dead | failed | restarting\n  MenuItem exitItem = null;\n  DateTime lastHttpCheck = DateTime.MinValue;\n  /** Body of the restart request already acted on (see ConsumeRestartRequest). */\n  string lastHandledRequest = null;\n\n  DshTray(LauncherConfig config, bool boot)\n  {\n    this.cfg = config;\n    this.boot = boot;\n  }\n\n  // ── lifecycle ────────────────────────────────────────────────────────────\n\n  /** Single-instance gate: ONE tray icon, ever, across BOTH binary copies\n   * (suite dsh-dock-launcher.exe and the desktop \"DSH Harness.exe\" differ\n   * in process NAME, so a name-based liveness check misfired and let a\n   * second icon in — a mutex is name-agnostic, race-free, and self-releases\n   * when the holder dies). */\n  static string MutexName(LauncherConfig cfg)\n  {\n    return \"Local\\\\dsh-dock-tray-\" + cfg.Port;\n  }\n\n  /** True when a tray holder exists (mutex object alive == process alive). */\n  internal static bool IsRunning(LauncherConfig cfg)\n  {\n    try\n    {\n      Mutex existing = Mutex.OpenExisting(MutexName(cfg));\n      existing.Dispose();\n      return true;\n    }\n    catch { return false; }\n  }\n\n  /** Create the tray and run its message loop until 完全退出. Losing the\n   * single-instance race (another tray already holds the mutex) exits\n   * silently — the winner keeps the one and only icon. */\n  internal static void Run(LauncherConfig cfg, bool boot)\n  {\n    Mutex gate = new Mutex(false, MutexName(cfg));\n    if (!gate.WaitOne(0))\n    {\n      DshDockProgram.Diag(\"tray: mutex held by another instance -> exit\");\n      return;\n    }\n    var tray = new DshTray(cfg, boot);\n    tray.gate = gate;\n    tray.Start();\n    Application.Run();\n    DshDockProgram.Diag(\"tray loop exited\");\n  }\n\n  void Start()\n  {\n    try\n    {\n      icon.Icon = System.Drawing.Icon.ExtractAssociatedIcon(Application.ExecutablePath);\n    }\n    catch { icon.Icon = SystemIcons.Application; }\n    icon.Visible = true;\n    icon.Text = \"DSH 启动中…\";\n    BuildMenu();\n    icon.MouseClick += delegate(object s, MouseEventArgs e)\n    {\n      if (e.Button == MouseButtons.Left) OpenDsh();\n    };\n    WriteTrayPid(cfg, System.Diagnostics.Process.GetCurrentProcess().Id);\n    Application.ApplicationExit += delegate { Cleanup(); };\n    // Initial facts: alive -> running; dead -> spawn only in boot mode\n    // (a user-visible cold start belongs to the card, not the tray).\n    bool alive = DshDockProgram.ServerAlive(cfg.Url);\n    state = alive ? \"running\" : (boot ? \"starting\" : \"dead\");\n    if (boot && !alive)\n    {\n      spawnWanted = true;\n      pendingOpen = false;\n    }\n    // Arm the restart-request watcher BEFORE the poller so the very first\n    // steady wait is already interruptible.\n    StartRestartWatch();\n    poller = new Thread(PollerLoop);\n    poller.IsBackground = true;\n    poller.Name = \"dsh-dock-tray-poller\";\n    poller.Start();\n  }\n\n  void Cleanup()\n  {\n    stopping = true;\n    Wake(); // release the poller from a 15s steady wait instead of waiting it out\n    try { if (restartWatch != null) restartWatch.Dispose(); } catch { }\n    WriteTrayPid(cfg, 0);\n    try { icon.Visible = false; icon.Dispose(); } catch { }\n    try { if (gate != null) gate.ReleaseMutex(); } catch { }\n    try { if (gate != null) gate.Dispose(); } catch { }\n  }\n\n  // ── adaptive pacing (v0.8) ───────────────────────────────────────────────\n\n  /**\n   * Cadence for the NEXT poll. Fast only where a human is waiting on a\n   * transition; a steady running server just needs the tooltip refreshed and\n   * the restart request noticed — and the latter is watcher-woken now.\n   */\n  int PollIntervalMs()\n  {\n    if (state == \"starting\" || state == \"restarting\") return PollActiveMs;\n    if (pendingOpen || spawnWanted) return PollActiveMs;\n    if (state == \"running\") return watchOk ? PollSteadyMs : PollActiveMs;\n    return PollIdleMs;\n  }\n\n  /**\n   * Watch the launcher directory for the sidebar's restart request so the\n   * steady-state interval can be long without delaying 洄游. Filtered to that\n   * one file on purpose: the directory also carries a server log that is\n   * written continuously, and watching everything would wake the poller as\n   * often as the old 1.5s heartbeat.\n   */\n  void StartRestartWatch()\n  {\n    try\n    {\n      string path = RestartPath(cfg);\n      string dir = string.IsNullOrEmpty(path) ? null : Path.GetDirectoryName(path);\n      if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir)) return;\n      restartWatch = new FileSystemWatcher(dir);\n      restartWatch.Filter = Path.GetFileName(path);\n      restartWatch.NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite;\n      restartWatch.Created += delegate { Wake(); };\n      restartWatch.Changed += delegate { Wake(); };\n      restartWatch.Renamed += delegate { Wake(); };\n      restartWatch.EnableRaisingEvents = true;\n      watchOk = true;\n      DshDockProgram.Diag(\"tray: restart watcher armed on \" + dir);\n    }\n    catch (Exception e)\n    {\n      // No watcher => PollIntervalMs() keeps the fast cadence, so 洄游 can\n      // never sit unanswered for a whole steady interval.\n      watchOk = false;\n      DshDockProgram.Diag(\"tray: restart watcher FAIL: \" + e.Message);\n    }\n  }\n\n  /** Nudge the poll loop out of its wait (watcher thread or shutdown). */\n  void Wake()\n  {\n    try { wake.Set(); } catch { }\n  }\n\n  /**\n   * Consume the sidebar restart request EXACTLY ONCE.\n   *\n   * The request file is written by the host and deleted here before the restart\n   * runs, but that delete can lose a race with the writer (the host still holds\n   * the handle for a few ms) and it used to be swallowed by an empty catch: the\n   * file survived, the restarting/starting guard only debounced it, and the very\n   * same request restarted the server a second time ~6s later — killing the\n   * instance it had just started. Detection used to be up to 1.5s late, which\n   * hid the race; the watcher now wakes the loop ~50ms after the write, so it\n   * bites. Hence: retry the delete, and remember the body — a request whose\n   * content was already handled is deleted and ignored, never restarted again.\n   * @returns true when this is a request the tray has not acted on yet.\n   */\n  bool ConsumeRestartRequest()\n  {\n    string path = RestartPath(cfg);\n    if (path == null) return false;\n    string body;\n    try\n    {\n      if (!File.Exists(path)) return false;\n      body = File.ReadAllText(path).Trim(); // throws while the host is mid-write\n    }\n    catch { return false; }                 // -> retried on the next tick\n    for (int attempt = 0; attempt < 5; attempt++)\n    {\n      try { File.Delete(path); break; }\n      catch { Thread.Sleep(120); }\n    }\n    if (body.Length > 0 && body == lastHandledRequest) return false;\n    lastHandledRequest = body;\n    return true;\n  }\n\n  // ── menu ─────────────────────────────────────────────────────────────────\n\n  void BuildMenu()\n  {\n    var open = new MenuItem(\"打开 DSH\", delegate { OpenDsh(); });\n    var restart = new MenuItem(\"重启服务器\", delegate { RestartServer(); });\n    var auto = new MenuItem(\"开机自启\", delegate { ToggleAutostart(); });\n    auto.Checked = ReadAutostart();\n    exitItem = new MenuItem(\"完全退出\", delegate { ExitClicked(); });\n    var sep = new MenuItem(\"-\");\n    var menu = new ContextMenu(new MenuItem[] { open, restart, auto, sep, exitItem });\n    // Refresh the autostart checkmark on EVERY popup: the state can also be\n    // written by the web settings page (settings/set -> registry), and a\n    // once-baked checkmark would show a stale state from tray start-up.\n    menu.Popup += delegate { auto.Checked = ReadAutostart(); };\n    icon.ContextMenu = menu;\n  }\n\n  /** 打开 DSH (also tray left-click): open now, or spawn + open when ready. */\n  void OpenDsh()\n  {\n    if (stopping) return;\n    DshDockProgram.Diag(\"tray: open\");\n    if (DshDockProgram.ServerAlive(cfg.Url))\n    {\n      if (TryOpenFromLog()) return;\n      state = \"starting\"; // alive but not ready yet — open when it is\n      pendingOpen = true;\n      return;\n    }\n    // Server dead: cold-start it from the tray (card-less), open when ready.\n    pendingOpen = true;\n    spawnWanted = true;\n    state = \"starting\";\n  }\n\n  /**\n   * 重启服务器: close every dock window -> marker -> kill the listener ->\n   * wait the port down -> clear the marker -> spawn the batch again -> open\n   * ONE fresh window when ready (user preference: no stale pre-restart pages;\n   * their tokens died with the old server anyway). This is the first-class\n   * restart the plugin never had (previously: full exit + double-click,\n   * ~15s of manual steps).\n   */\n  void RestartServer()\n  {\n    if (stopping || state == \"restarting\") return;\n    DshDockProgram.Diag(\"tray: restart server\");\n    state = \"restarting\";\n    pendingOpen = true;\n    // User preference: kill old dock windows first — they hold dead tokens\n    // once the listener dies; only the freshly auto-opened window remains.\n    CloseDockWindows();\n    WriteStoppingMarker();\n    foreach (int pid in ListenerPids())\n    {\n      try { System.Diagnostics.Process.GetProcessById(pid).Kill(); }\n      catch { }\n    }\n    // The poller's spawn path takes over once the port is really down.\n    spawnWanted = true;\n    spawned = false;\n  }\n\n  /** ☑开机自启: toggle the HKCU Run entry pointing at the suite exe --boot. */\n  void ToggleAutostart()\n  {\n    try\n    {\n      bool on = !ReadAutostart();\n      WriteAutostart(on, cfg);\n      icon.ContextMenu.MenuItems[2].Checked = on;\n      DshDockProgram.Diag(\"tray: autostart \" + (on ? \"on\" : \"off\"));\n    }\n    catch (Exception e)\n    {\n      DshDockProgram.Diag(\"tray: autostart FAIL: \" + e.Message);\n      Balloon(\"开机自启设置失败: \" + e.Message, ToolTipIcon.Error);\n    }\n  }\n\n  /** 完全退出 — single click (user preference: no two-step guard on the\n   * tray menu; the sidebar menu keeps its in-page two-step arm). */\n  void ExitClicked()\n  {\n    if (stopping) return;\n    if (exitItem != null) exitItem.Text = \"完全退出\";\n    DshDockProgram.Diag(\"tray: full exit\");\n    stopping = true;\n    WriteStoppingMarker();\n    foreach (int pid in ListenerPids())\n    {\n      try { System.Diagnostics.Process.GetProcessById(pid).Kill(); }\n      catch { }\n    }\n    DshDockProgram.WaitForPortDown(cfg, 15000);\n    CloseDockWindows();\n    TryDeleteMarker();\n    Application.Exit();\n  }\n\n  /**\n   * Close every DSH-dock Edge window — by IDENTITY (command line carries the\n   * dedicated --user-data-dir profile), not by spawn bookkeeping. Windows\n   * opened by a previous/double-click launcher outlive their spawner, and a\n   * tray that restarted mid-session would otherwise orphan them. Graceful\n   * close first, force-kill the survivors after a short grace.\n   */\n  void CloseDockWindows()\n  {\n    string profile = cfg.Profile ?? \"\";\n    var targets = new List<int>();\n    try\n    {\n      var searcher = new System.Management.ManagementObjectSearcher(\n        \"SELECT ProcessId, CommandLine FROM Win32_Process WHERE Name = 'msedge.exe'\");\n      foreach (var o in searcher.Get())\n      {\n        string cmd = Convert.ToString(o[\"CommandLine\"]);\n        if (string.IsNullOrEmpty(cmd) || profile.Length == 0) continue;\n        if (cmd.IndexOf(profile, StringComparison.OrdinalIgnoreCase) < 0) continue;\n        targets.Add(Convert.ToInt32(o[\"ProcessId\"]));\n      }\n      searcher.Dispose();\n    }\n    catch (Exception e) { DshDockProgram.Diag(\"CloseDockWindows enum FAIL: \" + e.Message); }\n    // Fallback: tracked windows when WMI enumeration failed.\n    if (targets.Count == 0)\n    {\n      foreach (Process p in edgeWindows)\n      {\n        try { if (!p.HasExited) targets.Add(p.Id); } catch { }\n      }\n    }\n    foreach (int pid in targets)\n    {\n      try { System.Diagnostics.Process.GetProcessById(pid).CloseMainWindow(); }\n      catch { }\n    }\n    System.Threading.Thread.Sleep(900);\n    foreach (int pid in targets)\n    {\n      try\n      {\n        var p = System.Diagnostics.Process.GetProcessById(pid);\n        if (!p.HasExited) p.Kill();\n      }\n      catch { }\n    }\n    edgeWindows.Clear();\n  }\n\n  // ── poller (background thread — probes block) ────────────────────────────\n\n  void PollerLoop()\n  {\n    while (!stopping)\n    {\n      // Reset BEFORE the pass: a request landing while PollOnce runs leaves the\n      // signal set, so the wait below returns at once instead of sleeping out\n      // the (now much longer) steady interval.\n      wake.Reset();\n      try { PollOnce(); }\n      catch (Exception ex) { DshDockProgram.Diag(\"tray poll FAIL: \" + ex.Message); }\n      if (stopping) break;\n      UpdateTooltip();\n      int waitMs = PollIntervalMs();\n      try { wake.Wait(waitMs); }\n      catch (ObjectDisposedException) { break; }\n    }\n    DshDockProgram.Diag(\"tray poller exit\");\n  }\n\n  void PollOnce()\n  {\n    if (stopping) return;\n    // Sidebar 重启服务器 request (host wrote .restart.request; the tray owns\n    // the restart sequence because the host cannot restart its own death).\n    if (state != \"restarting\" && state != \"starting\" && ConsumeRestartRequest())\n    {\n      DshDockProgram.Diag(\"tray: restart requested from sidebar\");\n      RestartServer();\n    }\n    bool alive = DshDockProgram.ServerAlive(cfg.Url);\n    if (alive)\n    {\n      state = \"running\";\n      spawned = false;\n      if (pendingOpen && (DateTime.UtcNow - lastHttpCheck).TotalMilliseconds\n        >= DshDockProgram.GateThrottleMs)\n      {\n        lastHttpCheck = DateTime.UtcNow;\n        if (TryOpenFromLog()) pendingOpen = false;\n      }\n      return;\n    }\n    // Port dead.\n    if (pendingOpen) spawnWanted = true;\n    if (spawnWanted && !spawned)\n    {\n      // Restart flow: the old listener must be fully down before a new one\n      // may take the port (start-server.cmd waits internally too, but the\n      // marker must not read \"fresh\" or the next double-click would stall).\n      if (state == \"restarting\")\n      {\n        if (!DshDockProgram.WaitForPortDown(cfg, 15000)) return; // still dying\n        TryDeleteMarker();\n      }\n      spawned = true;\n      spawnAt = DateTime.UtcNow;\n      try\n      {\n        DshDockProgram.Diag(\"tray spawn batch: \" + cfg.Batch);\n        var pi = new ProcessStartInfo(\"cmd.exe\", \"/c \\\"\" + cfg.Batch + \"\\\"\")\n        {\n          UseShellExecute = false,\n          CreateNoWindow = true,\n        };\n        spawnProc = System.Diagnostics.Process.Start(pi);\n        state = \"starting\";\n      }\n      catch (Exception ex)\n      {\n        DshDockProgram.Diag(\"tray spawn FAIL: \" + ex.Message);\n        state = \"failed\";\n        spawnWanted = false;\n        Balloon(\"服务器启动失败: \" + ex.Message + \"\\n日志:\" + cfg.Log, ToolTipIcon.Error);\n      }\n      return;\n    }\n    // Early death detection: the spawned batch exited without listening.\n    if (spawned && spawnProc != null && (DateTime.UtcNow - spawnAt).TotalSeconds > 4)\n    {\n      try\n      {\n        if (spawnProc.HasExited)\n        {\n          state = \"failed\";\n          spawned = false;\n          spawnWanted = false;\n          pendingOpen = false;\n          Balloon(\"服务器启动后立即退出(端口 \" + cfg.Port\n            + \")。日志:\" + cfg.Log, ToolTipIcon.Error);\n        }\n      }\n      catch { }\n      return;\n    }\n    if (state == \"running\") state = \"dead\"; // died without an exit request\n  }\n\n  void UpdateTooltip()\n  {\n    string text;\n    if (state == \"running\") text = \"DSH 运行中 · 端口 \" + cfg.Port;\n    else if (state == \"starting\" || state == \"restarting\") text = \"DSH 启动中… · 端口 \" + cfg.Port;\n    else if (state == \"failed\") text = \"DSH 启动失败 · 日志:\" + cfg.Log;\n    else text = \"服务器未运行 · 点左键打开\";\n    try { icon.Text = text.Length > 63 ? text.Substring(0, 63) : text; }\n    catch { }\n  }\n\n  void Balloon(string msg, ToolTipIcon kind)\n  {\n    try\n    {\n      icon.ShowBalloonTip(6000, \"DSH Dock\", msg, kind);\n    }\n    catch { }\n  }\n\n  /** Re-read the log, health-gate the token URL, open + adopt the window. */\n  bool TryOpenFromLog()\n  {\n    string url = DshDockProgram.ReadTokenUrl(cfg.Log);\n    if (url == null) return false;\n    if (!DshDockProgram.HttpReady(url)) return false;\n    DshDockProgram.Diag(\"tray open: \" + url);\n    Process p = DshDockProgram.LaunchEdge(url, cfg.Profile);\n    if (p != null) edgeWindows.Add(p);\n    return true;\n  }\n\n  // ── shared state files / registry ────────────────────────────────────────\n\n  /** Derive the manifest path (old inis lack the v0.4.0 keys). */\n  static string ManifestPath(LauncherConfig cfg)\n  {\n    if (!string.IsNullOrEmpty(cfg.Manifest)) return cfg.Manifest;\n    string dir = string.IsNullOrEmpty(cfg.Log) ? null : Path.GetDirectoryName(cfg.Log);\n    return dir == null ? null : Path.Combine(dir, \"launcher.json\");\n  }\n\n  static string SettingsPath(LauncherConfig cfg)\n  {\n    if (!string.IsNullOrEmpty(cfg.Settings)) return cfg.Settings;\n    string dir = string.IsNullOrEmpty(cfg.Log) ? null : Path.GetDirectoryName(cfg.Log);\n    return dir == null ? null : Path.Combine(dir, \"settings.json\");\n  }\n\n  /** Sidebar restart-request file (next to the other suite files). */\n  static string RestartPath(LauncherConfig cfg)\n  {\n    string dir = string.IsNullOrEmpty(cfg.Log) ? null : Path.GetDirectoryName(cfg.Log);\n    return dir == null ? null : Path.Combine(dir, \".restart.request\");\n  }\n\n  /** trayStay setting (default on when the file is missing/unreadable). */\n  internal static bool ReadTrayStay(LauncherConfig cfg)\n  {\n    try\n    {\n      string path = SettingsPath(cfg);\n      if (string.IsNullOrEmpty(path) || !File.Exists(path)) return true;\n      var ser = new System.Web.Script.Serialization.JavaScriptSerializer();\n      var root = ser.DeserializeObject(File.ReadAllText(path, System.Text.Encoding.UTF8))\n        as Dictionary<string, object>;\n      if (root != null && root.ContainsKey(\"trayStay\")) return Convert.ToBoolean(root[\"trayStay\"]);\n    }\n    catch { }\n    return true;\n  }\n\n  /** Stamp (or clear, pid<=0) trayPid inside launcher.json, merging keys. */\n  internal static void WriteTrayPid(LauncherConfig cfg, int pid)\n  {\n    try\n    {\n      string path = ManifestPath(cfg);\n      if (string.IsNullOrEmpty(path)) return;\n      var ser = new System.Web.Script.Serialization.JavaScriptSerializer();\n      Dictionary<string, object> root = null;\n      try\n      {\n        root = ser.DeserializeObject(File.ReadAllText(path, System.Text.Encoding.UTF8))\n          as Dictionary<string, object>;\n      }\n      catch { }\n      if (root == null) root = new Dictionary<string, object>();\n      if (pid > 0) root[\"trayPid\"] = pid;\n      else root.Remove(\"trayPid\");\n      File.WriteAllText(path, ser.Serialize(root), new System.Text.UTF8Encoding(false));\n    }\n    catch (Exception e) { DshDockProgram.Diag(\"WriteTrayPid FAIL: \" + e.Message); }\n  }\n\n  /** Suite exe the Run entry launches (stable path; falls back to self). */\n  static string AutostartExe(LauncherConfig cfg)\n  {\n    string dir = string.IsNullOrEmpty(cfg.Log) ? null : Path.GetDirectoryName(cfg.Log);\n    string exe = dir == null ? null : Path.Combine(dir, \"dsh-dock-launcher.exe\");\n    if (!string.IsNullOrEmpty(exe) && File.Exists(exe)) return exe;\n    return Application.ExecutablePath;\n  }\n\n  internal static bool ReadAutostart()\n  {\n    try\n    {\n      using (RegistryKey k = Registry.CurrentUser.OpenSubKey(RunKeySub))\n      {\n        return k != null && k.GetValue(RunValueName) != null;\n      }\n    }\n    catch { return false; }\n  }\n\n  internal static void WriteAutostart(bool on, LauncherConfig cfg)\n  {\n    using (RegistryKey k = Registry.CurrentUser.CreateSubKey(RunKeySub))\n    {\n      if (on) k.SetValue(RunValueName, \"\\\"\" + AutostartExe(cfg) + \"\\\" --boot\");\n      else k.DeleteValue(RunValueName, false);\n    }\n  }\n\n  // ── stop helpers (mirror the host route's semantics) ─────────────────────\n\n  /** PIDs LISTENING on our port (netstat, ~100ms; never Get-NetTCPConnection). */\n  List<int> ListenerPids()\n  {\n    var ids = new List<int>();\n    try\n    {\n      var pi = new ProcessStartInfo(\"netstat\", \"-ano\")\n      {\n        UseShellExecute = false,\n        CreateNoWindow = true,\n        RedirectStandardOutput = true,\n      };\n      using (Process p = Process.Start(pi))\n      {\n        string outText = p.StandardOutput.ReadToEnd();\n        p.WaitForExit(3000);\n        string portToken = \":\" + cfg.Port + \" \";\n        foreach (string raw in outText.Split('\\n'))\n        {\n          string line = raw.Trim();\n          if (!line.StartsWith(\"TCP\") || !line.Contains(\"LISTENING\")) continue;\n          if (!line.Contains(portToken)) continue;\n          string[] parts = line.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);\n          int pid;\n          if (int.TryParse(parts[parts.Length - 1], out pid) && pid > 0) ids.Add(pid);\n        }\n      }\n    }\n    catch (Exception e) { DshDockProgram.Diag(\"ListenerPids FAIL: \" + e.Message); }\n    // Never kill ourselves, whatever netstat says.\n    int self = Process.GetCurrentProcess().Id;\n    return ids.FindAll(delegate(int id) { return id != self; });\n  }\n\n  void WriteStoppingMarker()\n  {\n    try\n    {\n      long epoch = (long)(DateTime.UtcNow - new DateTime(1970, 1, 1)).TotalSeconds;\n      File.WriteAllText(cfg.Stopping, epoch.ToString());\n    }\n    catch { }\n  }\n\n  void TryDeleteMarker()\n  {\n    try { if (File.Exists(cfg.Stopping)) File.Delete(cfg.Stopping); }\n    catch { }\n  }\n}\n"
